select ss.store_id, case when year(ss.sale_date) < 2024 then 'before_2024' when year(ss.sale_date) = 2024 then '2024' else 'after_2024' end sale_cohort, max(i.quantity) max_quantity from inventory i inner join store_sales ss on i.store_id = ss.store_id and i.product_id = ss.product_id where i.store_id in (1, 4) group by ss.store_id, case when year(ss.sale_date) < 2024 then 'before_2024' when year(ss.sale_date) = 2024 then '2024' else 'after_2024' end order by sale_cohort desc, store_id desc limit 5
